/**
 * import-animation.js — copies the deaeration animation from its generator project into
 * components/ and applies this site's overrides (tools/animation-site-overrides.css).
 *
 *   node tools/import-animation.js [path/to/03-deaeration-analysis-and-air-x-retrofit.html]
 *
 * The animation is generated by tools/build-animations.js in the "Filter deaeration animation"
 * project. Don't edit components/03-deaeration-analysis-and-air-x-retrofit.html by hand; rerun
 * this after each rebuild there.
 */
const fs = require('fs');
const path = require('path');

const NAME = '03-deaeration-analysis-and-air-x-retrofit.html';
const SRC = process.argv[2] || path.join('D:/FINAL/Filter deaeration animation', NAME);
const OUT = path.join(__dirname, '..', 'components', NAME);
const CSS = path.join(__dirname, 'animation-site-overrides.css');

let html = fs.readFileSync(SRC, 'utf8');

function replaceOnce(from, to) {
  const n = html.split(from).length - 1;
  if (n !== 1) throw new Error(`expected one "${from}" in ${SRC}, found ${n}; the generated markup changed`);
  html = html.replace(from, to);
}

// The overrides restyle the stage; stop if the generator renamed it.
if (!html.includes('class="stage"')) throw new Error(`missing class="stage" in ${SRC}; update tools/animation-site-overrides.css`);

replaceOnce('</head>', `<style id="site-overrides">\n${fs.readFileSync(CSS, 'utf8')}</style>\n</head>`);

fs.writeFileSync(OUT, html);
console.log(`wrote ${path.relative(process.cwd(), OUT)} from ${SRC}`);
